input.sparql:
PREFIX brick: <http://brickschema.org/brick#>
PREFIX ref: <http://w3id.org/en-core/reference#>
SELECT WHERE {
  ?p a brick:Electric_Power .
  ?p ref:hasExternalReference ?ts .
  ?ts ref:hasTimeseriesId ?id .
  OPTIONAL { ?p brick:hasParentLocation ?par ; brick:hasTag ?tag }
  ?p rdfs:label ?lbl .
  FILTER(?id)
}
